from h import *
R(9873294,"كروستيني نباتي بـ «الريكوتا» والفطر",
"كروستيني نباتي مقرمش وبنكهة الجبن وطازج ولذيذ بشكل لا يُصدَّق، مقبلات مثالية لأي وجبة.",
"6 حصص","حصة واحدة",
["1 رغيف باغيت أو خبز من اختيارك","454 غرام (16 أونصة) فطر كريميني مقطع إلى شرائح رفيعة","ملح وفلفل حسب الرغبة","350 غرام (12 أونصة) قالب توفو شديد الصلابة مصفى (اختر نوعًا خاليًا من التعديل الوراثي إن أمكن)","¼ كوب خميرة غذائية","3 ملاعق كبيرة خل التفاح","1 ملعقة صغيرة ملح البحر","½ ملعقة صغيرة مسحوق الثوم","صلصة بلسمي مركزة (غلاز)","ريحان طازج مفروم"],
["سخّن الفرن مسبقًا على 375° فهرنهايت (190° مئوية) بوضع الخبز. ثم قطّع الباغيت إلى شرائح بسماكة ربع بوصة ورتّبها في طبقة واحدة على صينية خبز كبيرة (أو صينيتين عند الحاجة). اخبز الخبز لمدة 5-8 دقائق، أو حتى يصبح ذهبيًا ومقرمشًا.",
"في الأثناء، قلّب الفطر دون إضافة دهون مع رشة من الملح والفلفل (سيُخرج الكثير من الرطوبة ولن يلتصق بالمقلاة) حتى يتقلص، حوالي 3-4 دقائق. اتركه جانبًا.",
"بعد ذلك، ضع جميع مكونات الريكوتا في محضّرة الطعام واخلطها حتى تصبح ناعمة ومتجانسة في معظمها. يجب أن تكون سميكة لكن قابلة للدهن.",
"اجمع الكروستيني النباتي بدهن الريكوتا على كل شريحة من الخبز المحمص، ثم ضع فوقها بضع شرائح من الفطر، وأخيرًا رش عليها صلصة البلسمي المركزة وانثر الريحان المفروم."],
["حضّر مسبقًا بتجهيز خليط جبن الريكوتا وضعه في الثلاجة حتى الحاجة إليه.","خطّط لتناول هذا الكروستيني فورًا، فطعمه أفضل وهو طازج.","تعطي وصفة الكروستيني النباتي هذه حوالي 4 حصص كوجبة، أو 6-8 حصص كمقبلات. وتمثل المعلومات الغذائية أعلاه 6 حصص، كل منها حوالي 2-3 شرائح كروستيني مع إضافاتها. (وهذا سيختلف حسب حجم الرغيف وسماكة الشرائح.)"],
{"For the vegan ricotta":"للريكوتا النباتية","For garnish":"للتزيين"})
R(9874640,"حليب الكاجو المنزلي السهل",
"حليب الكاجو المنزلي سهل للغاية وهو البديل المثالي للحليب الخالي من الألبان. استخدمه بنسبة واحد إلى واحد بدلًا من حليب الألبان.",
"5 أكواب","0.5 كوب",
["1 كوب كاجو نيء منقوع في ماء مغلي لمدة 30 دقيقة","4 أكواب ماء مفلتر","1-2 ملعقة كبيرة شراب القيقب","1-2 حبة تمر منزوعة النوى"],
["صفِّ الكاجو وضعه في الخلاط مع الماء والمحلي الذي تختاره، إن استخدمته، واخلطه حتى يصبح ناعمًا.",
"باستخدام كيس حليب المكسرات (Bigger & Better Nut Milk Bag)، أو ما يعادله، صفِّ الحليب في إبريق لإزالة أي قطع وتفل متبقية لتحصل على حليب كاجو ناعم وكريمي ومثالي."],
["احفظه في الثلاجة في وعاء مغطى أو إبريق بغطاء. استهلكه خلال 5 أيام."],
{"Optional Sweeteners":"محليات اختيارية"})
R(9876454,"بروسكيتا الفطر (Bruschetta ai funghi)",
"لذيذة وترابية ومليئة بالنكهة، وصفة بروسكيتا الفطر هذه هي الكمال بعينه.",
"6 حصص","شريحتان",
["1 رغيف باغيت مقطع إلى شرائح بسماكة ¼ بوصة","227 غرام فطر أبيض أو كريميني مقطع إلى شرائح","1 فص ثوم مفروم","1 ملعقة كبيرة صلصة صويا","1 حبة طماطم روما مقطعة إلى مكعبات","1 ملعقة كبيرة خل بلسمي","1 ملعقة كبيرة عصير ليمون","2 ملعقة كبيرة ريحان طازج مفروم","ملح وفلفل حسب الرغبة"],
["سخّن الفرن مسبقًا على 375° فهرنهايت (190° مئوية) وجهّز صينية خبز كبيرة.",
"أثناء انتظار تسخين الفرن، قلّب الفطر والثوم وصلصة الصويا حتى يتقلص. اتركه جانبًا.",
"قطّع الخبز ورتّبه في طبقة واحدة، واخبزه لمدة 5-8 دقائق، حتى يصبح ذهبيًا جميلًا.",
"بينما يُحمَّص الخبز، اخلط الفطر المقلّب مع جميع المكونات المتبقية (باستثناء الخبز) في وعاء خلط. تذوّق للتأكد من الملح والفلفل وعدّلهما عند الحاجة.",
"بعد أن يتحمص الخبز ويصبح ذهبيًا، ضع الخليط بالملعقة على شرائح الخبز وقدّمها."],
["خطّط لتناول بروسكيتا الفطر فورًا، فطعمها أفضل وهي طازجة.","تستند المعلومات الغذائية إلى تقطيع الباغيت إلى 12 شريحة، وتمثل حجم الحصة حوالي شريحتين من بروسكيتا الفطر."],
{})
R(9877958,"سلطة البروكلي والتوت البري مع صلصة بذور الخشخاش [خالية من الزيت]",
"مشرقة وممتعة ولذيذة! سلطة البروكلي والتوت البري هذه مقرمشة وغنية، تجمع بين الحلو والحامض ويسيل لها اللعاب. مثالية للأعياد وحفلات المسبح والولائم التي يُحضر فيها كل ضيف طبقًا.",
"6 حصص","حصة واحدة",
["6 أكواب زهيرات بروكلي مقطعة إلى قطع صغيرة بحجم لقمة","علبة حمص 15 أونصة مصفاة ومغسولة","½ كوب بيكان أو جوز","½ كوب توت بري مجفف غير محلى","¼ كوب بصل أحمر مفروم ناعمًا","1 حبة تفاح أخضر مقطعة إلى مكعبات","1 ملعقة كبيرة عصير ليمون","¾ كوب كاجو نيء*","¾ كوب ماء","3 ملاعق كبيرة عصير ليمون أو خل التفاح","2 ملعقة كبيرة شراب القيقب","¼ ملعقة صغيرة ملح البحر","1 ملعقة صغيرة بذور الخشخاش"],
["قطّع التفاح إلى مكعبات وضعه في وعاء كبير. ثم اعصر عصير الليمون الطازج فوقه لمنعه من الاسمرار وامزج جيدًا. أضف جميع مكونات السلطة المتبقية إلى الوعاء نفسه وامزجها معًا.",
"ضع جميع مكونات الصلصة باستثناء بذور الخشخاش في الخلاط وشغّله حتى يصبح ناعمًا. ثم أضف بذور الخشخاش واخلط لمدة 1-2 ثانية، بما يكفي لمزجها في الصلصة. اسكب الصلصة على السلطة وامزج جيدًا وضعها في الثلاجة لمدة ساعة أو أكثر قبل التقديم."],
["* إذا لم يكن لديك خلاط قوي، مثل فيتامكس أو بليندتك، فانقع الكاجو في ماء مغلي لمدة 30 دقيقة على الأقل، ثم صفِّه قبل الخلط. سيساعد ذلك على تليين الكاجو بما يكفي ليُخلط ناعمًا. ستلاحظ أن الوصفة تتطلب عصير الليمون مرتين. فالمرة الأولى لمنع التفاح من الاسمرار ولإضافة النكهة. والمرة الثانية لصلصة السلطة بذور الخشخاش. وكلتاهما ضرورية. استخدم تفاحًا حامضًا، مثل غراني سميث، للحصول على أفضل نكهة لاذعة. لا تخلط بذور الخشخاش مع الصلصة في الخلاط. احرص على إضافتها فقط بعد معالجة الصلصة. للحصول على أفضل نكهة، برّدها لمدة ساعة (أو أكثر) قبل التقديم. ومع ذلك، إذا لم يسمح الوقت، فيمكنك تناولها فورًا."],
{"For the Salad":"للسلطة","For the Dressing":"للصلصة"})
R(9882145,"هوت دوغ نباتي [سجق السيتان]",
"سجق السيتان غني بالنكهة وسهل التحضير وأكثر صحة من الجاهز! مثالي لحفلات الشواء!",
"8 قطع سجق سيتان","حصة واحدة",
["1 كوب فاصولياء بيضاء (كانيليني) مصفاة ومغسولة ومجففة بالتربيت","1 كوب مرق خضار قليل الصوديوم","3 ملاعق كبيرة صلصة صويا","2 ملعقة كبيرة معجون طماطم","1 ملعقة كبيرة شراب القيقب","1 ملعقة كبيرة خل التفاح","270 غرام غلوتين القمح الحيوي (Vital wheat gluten) (حوالي 2 كوب)","3 ملاعق صغيرة مسحوق البصل","2.5 ملعقة صغيرة مسحوق الثوم","2 ملعقة صغيرة بابريكا مدخنة أو حلوة","1 ملعقة صغيرة ملح البحر","½ ملعقة صغيرة بهارات الدواجن","½ ملعقة صغيرة كزبرة مطحونة","¼ ملعقة صغيرة كركم","¼ ملعقة صغيرة جوزة الطيب","¼ ملعقة صغيرة فلفل أسود","خبز الهوت دوغ","خردل وكاتشب ومخلل مقطع (ريليش) وهالبينو وفلفل حار وسلطة ملفوف (كولسلو)"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175° مئوية) (إذا كنت تستخدم طريقة الفرن) وقصّ 8 قطع من ورق الألمنيوم (وورق الزبدة إن فضّلت ألا يلامس الألمنيوم طعامك) واتركها جانبًا.",
"ضع الفاصولياء البيضاء في وعاء خلط واهرسها برفق بشوكة كبيرة أو مهراس بطاطس. (لا يلزم هرسها بالكامل، فلا بأس ببعض القطع الأكثر خشونة.) ثم أضف جميع المكونات السائلة المتبقية إلى الوعاء نفسه وامزج جيدًا.",
"الآن أضف جميع المكونات الجافة وابدأ بالخلط حتى تتجمع في معظمها على شكل كرة عجين. ثم انقلها إلى لوح تقطيع أو سطح عمل نظيف واعجنها لمدة دقيقة واحدة تقريبًا، حتى تحصل على خليط متجانس، لكن لا تفرط في العجن.",
"قسّم العجين إلى 8 قطع وشكّل كل قطعة على هيئة أسطوانة لصنع الهوت دوغ النباتي. (لا تقلق إن كانت غير مستوية، فستصبح ناعمة عند الطهي.) ثم لفّ كل قطعة سجق سيتان بورق الزبدة (إن استخدمته) وورق الألمنيوم ولُفّ الأطراف لإحكام إغلاقها. (انظر صور الخطوات أعلاه للتوضيح.) اختر طريقة الطهي أدناه.",
"اترك قدرًا كبيرًا فيه بضع بوصات من الماء حتى يغلي وضع سلة البخار بداخله. تأكد من أن السلة لا تلامس الماء. وعند الغليان، اخفض الحرارة للحفاظ على غليان هادئ وضع قطع سجق السيتان بداخلها. غطِّ القدر واطهُها على البخار لمدة 45-55 دقيقة، مع قلبها عند منتصف المدة. تفقّد الماء من حين لآخر وأضف ماءً ساخنًا عند الحاجة. أخرج الهوت دوغ من السلة واتركه يبرد 5 دقائق قبل نزع ورق الألمنيوم.",
"ضع قطع سجق السيتان الملفوفة على صينية واخبزها لمدة 45 دقيقة، مع قلبها عند منتصف المدة. أخرجها من الفرن واتركها تبرد حوالي 5 دقائق قبل نزع ورق الألمنيوم.",
"ضع 1.5 كوب من الماء في قاع إنستانت بوت. ثم ضع الحامل المعدني (تريفيت) داخل القدر. رتّب قطع سجق السيتان الملفوفة على الحامل، مع تكديسها عند الحاجة. ثم أغلق الغطاء وتأكد من أن الصمام في وضع الإغلاق. اطهُها على البخار لمدة 45 دقيقة واترك قدرك يحرر الضغط تلقائيًا حتى يسقط المؤشر. أخرجها عندما يكون ذلك آمنًا.",
"يمكنك تناولها فور الخبز أو الطهي على البخار. أو يمكنك شواء سجق السيتان للحصول على خطوط الشواء الجميلة. افرد على الهوت دوغ النباتي بعض الزيت بالفرشاة (إن رغبت) وانثر قليلًا من الملح والفلفل الإضافيين. ثم اشوه لمدة 1-2 دقيقة لتعزيز النكهات.",
"قدّمه مع خبز الهوت دوغ وجميع الإضافات المفضلة لديك. بالهناء والشفاء!"],
["للحصول على أدق النتائج، زِن غلوتين القمح الحيوي. وإذا لم يكن لديك ميزان مطبخ، فاستخدم ما يعادل كوبين. احرص على خلط العجين جيدًا للحصول على نكهة متجانسة وأفضل قوام، لكن لا تفرط في العجن. فالعجن لمدة 1-2 دقيقة مثالي. لا تُطِل الانشغال بالحصول على شكل مثالي للهوت دوغ. فسيكون غير مستوٍ قبل الطهي، لكنه يصبح ناعمًا جدًا أثناء الطهي. وإذا كنت لا تحب أن يلامس ورق الألمنيوم طعامك، فاستخدم ورق الزبدة بين قطع سجق السيتان وطبقة ورق الألمنيوم. وللحصول على سجق نباتي حار، أضف 1 ملعقة صغيرة من رقائق الفلفل الحار إلى الخليط. للتحضير المسبق: جهّز واطهُ السجق بالكامل قبل 1-2 يوم بالطريقة التي تختارها (البخار أو الخبز) ثم اشوه قبل التقديم مباشرة. يُحفظ المتبقي في الثلاجة لمدة تصل إلى 5 أيام أو يُجمَّد لمدة تصل إلى 3 أشهر. كيف أعرف أنه نضج؟ انزع ورق الألمنيوم برفق، ويجب أن يبدو الهوت دوغ ناعمًا. يمكنك الضغط عليه بإصبعك أو بملقط لاختبار تماسكه. يجب أن يكون متماسكًا لكن يلين قليلًا عند الضغط. وسيزداد تماسكًا أكثر عند التبريد."],
{"Wet Ingredients":"المكونات السائلة","Dry Ingredients":"المكونات الجافة","Optional Toppings":"إضافات اختيارية","Steaming Instructions":"طريقة البخار","Baking Instructions":"طريقة الخبز","Instant Pot Instructions":"طريقة إنستانت بوت","Optional Grilling":"شواء اختياري"})
R(9882257,"مافن الموز والحمص",
"رطب وصحي وغني بالبروتين، مافن الموز والحمص هذا لمسة صحية لذيذة على طبق مفضل كلاسيكي.",
"12 كعكة مافن","حصة واحدة",
["2 كوب (علبة 18 أونصة) حمص مصفى ومغسول","3 حبات موز متوسطة (1 كوب مهروس)","½ كوب طحينة أو زبدة اللوز","¼ كوب سكر جوز الهند غير المكرر","1.5 كوب شوفان مجروش (خالٍ من الغلوتين إن فضّلت)","1 ملعقة كبيرة مستخلص الفانيليا الطبيعي","2 ملعقة صغيرة بيكنغ باودر","شرائح موز، رقائق شوكولاتة، توت أزرق، مكسرات"],
["سخّن الفرن مسبقًا على 350° فهرنهايت (175° مئوية) واستخدم قالب مافن مدهونًا أو بطّن قالب المافن بأكواب ورقية.",
"اهرس الموز للتأكد من أن لديك كوبًا واحدًا من الموز المهروس. ثم أضف جميع المكونات باستثناء أي إضافات اختيارية إلى محضّرة الطعام. شغّل المحضّرة حتى يصبح الخليط ناعمًا في معظمه.",
"وزّع العجينة على أكواب المافن الـ 12 وضع الإضافات فوق بعض المافن أو كلها إن رغبت.",
"اخبز مافن الحمص لمدة 20-22 دقيقة أو حتى تخرج عود الأسنان نظيفة في معظمها عند غرسها في وسط المافن. ثم أخرجه من الفرن واتركه يبرد 10-15 دقيقة قبل نقله إلى رف التبريد."],
["استخدم موزًا شديد النضج. فكلما كان الموز أنضج، أضاف نكهة وحلاوة ورطوبة أكبر إلى مافن الموز والحمص. والموز ذو القشرة البنية هو الأفضل.","استخدم بيكنغ باودر طازجًا وفعّالًا. فالبيكنغ باودر المفتوح في المخزن لأكثر من 6 أشهر قد تضعف فعاليته.","قِس الموز المهروس للتأكد من أنك تستخدم كوبًا واحدًا. فحجم الموز يختلف كثيرًا. وقد نجحت معي موزتان كبيرتان أو ثلاث موزات متوسطة.","اترك المافن يبرد 10-15 دقيقة قبل إخراجه من قالب المافن ليتماسك ولمنعه من التكسر.","يُحفظ المافن المتبقي في درجة حرارة الغرفة لمدة 1-2 يوم، وفي الثلاجة لمدة تصل إلى 5 أيام أو مجمدًا لمدة تصل إلى 3 أشهر."],
{"Optional toppings":"إضافات اختيارية"})
R(9882910,"مقلي لفائف الصويا السهل [مقلي نباتي]",
"مقلي لفائف الصويا الغني بالنكهة، سهل التحضير وجاهز في 30 دقيقة أو أقل.",
"4 حصص","حصة واحدة",
["4 أونصات لفائف الصويا (حوالي نصف كيس لفائف الصويا من Butler's)","6-8 أكواب خضار مجمدة للقلي","2 كوب مرق خضار قليل الصوديوم","⅓ كوب صلصة صويا قليلة الصوديوم أو تاماري للخالي من الغلوتين","¼ كوب خل الأرز","¼ كوب ماء عذب","2 ملعقة كبيرة شراب القيقب","2 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة مسحوق الزنجبيل","2 ملعقة كبيرة نشا الذرة أو دقيق التابيوكا","شعيرية الأرز، أرز بني، كينوا، نودلز الخضار، أرز القرنبيط","بذور السمسم والبصل الأخضر و/أو رقائق الفلفل الأحمر للتزيين"],
["اخلط جميع مكونات التتبيلة باستثناء نشا الذرة في وعاء كبير. ثم أضف لفائف الصويا الجافة إلى الوعاء وحرّكها واتركها تنقع لمدة 10 دقائق.",
"سخّن مقلاة من الحديد الزهر، أو ما يماثلها، على حرارة متوسطة إلى عالية. ثم انتشل لفائف الصويا المتبلة من الوعاء (لا تصفِّها - احتفظ بالصلصة) وضعها في المقلاة لتقليبها حتى تتحمر، حوالي 4-5 دقائق، مع التحريك المتكرر.",
"بعد ذلك أضف الخضار، مع التحريك من حين لآخر لمدة 4-5 دقائق أخرى.",
"في الأثناء، حرّك نشا الذرة في وعاء التتبيلة المحتفظ به. ثم اسكب الصلصة في المقلاة مع لفائف الصويا والخضار. اتركها على نار هادئة لتثخن لمدة 2-3 دقائق قبل التقديم."],
["استخدم مرقًا وصلصة صويا قليلي الصوديوم للتتبيلة لتجنب أن يصبح الطبق مالحًا جدًا. استخدم نصف ماء ونصف مرق إذا لم يكن لديك مرق قليل الصوديوم. (يمكنك دائمًا إضافة الملح لاحقًا عند الحاجة.)","لا تفرط في طهي الخضار! فطعمها أفضل عندما تكون طرية ومقرمشة للحصول على أفضل قوام.","احفظ أي متبقٍّ في الثلاجة لمدة 3-4 أيام أو جمّده في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر."],
{"For the marinade":"للتتبيلة","For serving (optional)":"للتقديم (اختياري)"})
R(9889051,"بان كيك التوت الأزرق النباتي الصحي",
"بان كيك التوت الأزرق النباتي هش وسميك وخالٍ من السكر وشهي تمامًا.",
"8 قطع بان كيك","قطعة بان كيك واحدة",
["1.5 كوب حليب الصويا","1.5 ملعقة صغيرة خل التفاح","1 كوب شوفان مجروش (خالٍ من الغلوتين إن فضّلت)","2 ملعقة كبيرة بذور الشيا","2 ملعقة كبيرة بذور القنب المقشرة (هيمب هارتس)","⅓ كوب دقيق الحمص (يُعرف أيضًا بدقيق الغاربانزو)","2 ملعقة صغيرة بيكنغ باودر","1 كوب توت أزرق طازج"],
["سخّن مقلاة مسطحة غير لاصقة (غريدل) على حرارة متوسطة. ثم ضع حليب الصويا وخل التفاح في وعاء صغير واتركه جانبًا ليتخثر.",
"في الأثناء، ضع الشوفان وبذور القنب وبذور الشيا في الخلاط وشغّله حتى يصبح بقوام الدقيق. (لا تقلق إن وُجدت بعض القطع الأخشن.) انقله إلى وعاء خلط كبير وأضف دقيق الحمص والبيكنغ باودر واخفق حتى يمتزج.",
"يجب أن يكون الحليب قد تخثر الآن، فاسكبه في وعاء الدقيق وامزج حتى يمتزج دون إفراط في الخلط. أضف التوت الأزرق بطيّه برفق.",
"اغرف العجينة على المقلاة المسخنة مسبقًا لتصنع بان كيك بقطر 4 بوصات تقريبًا. يمكنك الضغط على البان كيك برفق ليساعد ذلك على الانتشار قليلًا لأن العجينة لن تكون سائلة جدًا. ومع ذلك، لا تفرط في فردها لأن طعمها أفضل عندما تكون سميكة وهشة قليلًا.",
"اطهُها لمدة 4-5 دقائق حتى تصبح ذهبية، ثم اقلبها واطهُها 3-4 دقائق أخرى، حتى تنضج تمامًا.",
"قدّمه مع مزيد من التوت الأزرق الطازج أو التوت الأحمر (راسبيري) أو جوز الهند المبشور أو رقائق الشوكولاتة أو المكسرات أو شراب القيقب."],
["تأكد من أن البيكنغ باودر فعّال. فإذا بقي مفتوحًا في مخزنك لأكثر من 6 أشهر، فقد يبدأ بفقدان فعاليته.","لا يلزم خلط الشوفان والبذور خلطًا مثاليًا. فإذا بقيت بعض القطع الرقيقة التي لا تُطحن، فسيظل البان كيك ممتازًا.","لا حاجة للإفراط في خلط عجينة البان كيك. فإذا وُجدت بعض التكتلات فلا بأس بذلك إطلاقًا. فقط امزج حتى يمتزج الخليط ولا تبقى كتل دقيق.","استخدم حرارة متوسطة للطهي المتساوي. فالحرارة العالية ستطهو الخارج بسرعة كبيرة، مما يترك الداخل غير ناضج. لكن تأكد من أن المقلاة مسخنة مسبقًا حتى لا يلتصق البان كيك!","يُحفظ المتبقي في الثلاجة لمدة 3-4 أيام أو يُجمَّد في أكياس بسحّاب أو وعاء مناسب للمجمّد لمدة تصل إلى 3 أشهر. أعد تسخينه في محمصة الخبز لوجبات إفطار سريعة وسهلة."],
{})
